+                phone.getValue().trim(), message.getValue(), Instant.now()));
+        grid.setItems(service.findAll());
+
+        clearing = true;
+        try {
+            name.clear();
+            email.clear();
+            phone.clear();
+            message.clear();
+        } finally {
+            clearing = false;
+        }
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
